import express, { NextFunction, Request, Response } from "express";
import { ApplicationError } from "../application/application-error";
import { CreateProjectUseCase } from "../application/create-project-use-case";
import { CreateTaskUseCase } from "../application/create-task-use-case";
import { CreateUserUseCase } from "../application/create-user-use-case";
import { ListProjectTasksUseCase } from "../application/list-project-tasks-use-case";
import { MarkTaskDoneUseCase } from "../application/mark-task-done-use-case";
import { InMemoryProjectRepository } from "./in-memory-project-repository";
import { InMemoryTaskRepository } from "./in-memory-task-repository";
import { InMemoryUserRepository } from "./in-memory-user-repository";
import { ProjectController } from "./project-controller";
import { TaskController } from "./task-controller";
import { UserController } from "./user-controller";
import { UuidGenerator } from "./uuid-generator";

export function createHttpServer() {
  const app = express();
  const ids = new UuidGenerator();
  const projects = new InMemoryProjectRepository();
  const users = new InMemoryUserRepository();
  const tasks = new InMemoryTaskRepository();
  const usersController = new UserController(new CreateUserUseCase(users, ids));
  const projectsController = new ProjectController(new CreateProjectUseCase(projects, ids));
  const tasksController = new TaskController(
    new CreateTaskUseCase(tasks, projects, users, ids),
    new ListProjectTasksUseCase(tasks, projects),
    new MarkTaskDoneUseCase(tasks),
  );

  app.use(express.json());
  app.post("/users", usersController.create);
  app.post("/projects", projectsController.create);
  app.post("/projects/:projectId/tasks", tasksController.create);
  app.get("/projects/:projectId/tasks", tasksController.list);
  app.patch("/tasks/:taskId/done", tasksController.complete);
  app.use(errorHandler);
  return app;
}

function errorHandler(error: unknown, _request: Request, response: Response, _next: NextFunction): void {
  if (error instanceof ApplicationError) {
    response.status(error.statusCode).json({ error: error.message });
    return;
  }
  response.status(500).json({ error: "internal server error" });
}

