import { TaskRepository, TaskFilter } from "../domain/task-repository";
import { Task } from "../domain/task";

export class InMemoryTaskRepository implements TaskRepository {
  private readonly tasks = new Map<string, Task>();

  public async save(task: Task): Promise<void> {
    this.tasks.set(task.id, task);
  }

  public async findById(id: string): Promise<Task | undefined> {
    return this.tasks.get(id);
  }

  public async findByProjectId(projectId: string, filter: TaskFilter): Promise<Task[]> {
    return [...this.tasks.values()].filter((task) =>
      task.projectId === projectId &&
      (!filter.status || task.getStatus() === filter.status) &&
      (!filter.assigneeId || task.assigneeId === filter.assigneeId),
    );
  }
}

