import { NextFunction, Request, Response } from "express";
import { CreateTaskUseCase } from "../application/create-task-use-case";
import { ListProjectTasksUseCase } from "../application/list-project-tasks-use-case";
import { MarkTaskDoneUseCase } from "../application/mark-task-done-use-case";
import { ApplicationError } from "../application/application-error";
import { isTaskStatus } from "../domain/task-status";

export class TaskController {
  public constructor(
    private readonly createTask: CreateTaskUseCase,
    private readonly listTasks: ListProjectTasksUseCase,
    private readonly markDone: MarkTaskDoneUseCase,
  ) {}

  public create = async (request: Request, response: Response, next: NextFunction): Promise<void> => {
    try {
      const body = request.body as Record<string, unknown>;
      const status = body?.status;
      if (status !== undefined && !isTaskStatus(status)) throw new ApplicationError("invalid task status", 400);
      response.status(201).json(await this.createTask.execute({
        projectId: this.text(request.params.projectId),
        title: this.text(body?.title), description: this.text(body?.description),
        dueDate: typeof body?.dueDate === "string" ? body.dueDate : undefined,
        assigneeId: typeof body?.assigneeId === "string" ? body.assigneeId : undefined,
        status,
      }));
    } catch (error) { next(error); }
  };

  public list = async (request: Request, response: Response, next: NextFunction): Promise<void> => {
    try {
      const status = request.query.status;
      if (status !== undefined && !isTaskStatus(status)) throw new ApplicationError("invalid task status", 400);
      const assignee = request.query.assigneeId;
      if (assignee !== undefined && typeof assignee !== "string") throw new ApplicationError("invalid assigneeId", 400);
      response.json(await this.listTasks.execute({ projectId: this.text(request.params.projectId), status, assigneeId: assignee }));
    } catch (error) { next(error); }
  };

  public complete = async (request: Request, response: Response, next: NextFunction): Promise<void> => {
    try { response.json(await this.markDone.execute(this.text(request.params.taskId))); } catch (error) { next(error); }
  };

  private text(value: unknown): string { return typeof value === "string" ? value : ""; }
}

